/* Evidence integrity (js/data-evidence.js, generated by build/kb/verify.py --write):
   - every quoted verse and hadith has a verification record, made for exactly the text that ships (fingerprint);
   - nothing unverified is in the library used for answers, and answers never cite it.
   node build/tests/test-evidence.js */
const path = require("path");
const JS = process.env.BENCH_JS || path.join(__dirname, "../../js");
const L = require("./load.js")(JS, "ar");
let fail = 0; const bad = (m) => { fail++; console.log("FAIL " + m); };
function fp(text) {   // FNV-1a over UTF-16 code units, as fingerprint() in build/kb/kbsrc.py
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) { h ^= text.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, "0");
}
const E = L.EVIDENCE;
if (!E) { console.log("FAIL js/data-evidence.js not loaded"); process.exit(1); }
const items = [];
L.QURAN_LIB.forEach(q => items.push([q.id, q.t, "quran"]));
L.HADITH_ALL.forEach(h => items.push([h.id, h.t, "hadith"]));
L.SITUATIONS.forEach(s => {
  (s.quranRefs || []).forEach((q, i) => items.push([s.id + "#q" + i, q.text, "quran"]));
  (s.hadithRefs || []).forEach((h, i) => items.push([s.id + "#" + i, h.text, "hadith"]));
});
const stale = [];
items.forEach(([id, text, kind]) => {
  const e = E[id];
  if (!e) return bad("no verification record for " + id + " — run python -I build/kb/verify.py --write");
  if (e.f !== fp(text)) stale.push(id);
  const ok = kind === "quran" ? ["verified", "excerpt"] : ["source", "secondary", "summary", "unverified"];
  if (ok.indexOf(e.v) < 0) bad(id + ": status «" + e.v + "» is not acceptable for a " + kind + " quotation");
});
if (stale.length) bad("text changed since it was verified (" + stale.length + "): " + stale.slice(0, 8).join(", ") + " — run python -I build/kb/verify.py --write");
// summaries must be labelled as such in the UI data
L.SITUATIONS.forEach(s => (s.hadithRefs || []).forEach((h, i) => { const e = E[s.id + "#" + i]; if (e && e.v === "summary" && !h.paraphrase) bad(s.id + "#" + i + " is a summary but not marked paraphrase:true"); }));
const hidden = L.HADITH_ALL.filter(h => E[h.id] && E[h.id].v === "unverified").map(h => h.id);
const leaked = L.HADITH_LIB.filter(h => hidden.indexOf(h.id) > -1);
if (leaked.length) bad("unverified hadith still in the answer library: " + leaked.map(h => h.id).join(", "));
// answers never cite them (a broad sample: every theme's own words)
let cited = 0;
L.THEMES.forEach(t => {
  const a = L.RAG.analyze(t.triggers.slice(0, 4).join(" ") + " " + t.label);
  (a.retrieval.hadith || []).concat(a.retrieval.duas || []).forEach(x => { const id = (x.item || x.h || x).id; if (hidden.indexOf(id) > -1) cited++; });
});
if (cited) bad("answers cite unverified hadith " + cited + " times");
const count = (k) => Object.values(E).filter(e => e.v === k).length;
console.log("evidence: " + items.length + " quotations · hadith source " + count("source") + ", secondary " + count("secondary") + ", summary " + count("summary") + ", unverified (hidden) " + count("unverified") + " · quran verified " + count("verified") + ", excerpt " + count("excerpt"));
console.log(fail ? fail + " failure(s)" : "evidence tests passed");
process.exit(fail ? 1 : 0);
